ORDER = ["ads", "seo-geo", "maps", "smm-telegram", "web", "production"]


PRICES = {
 "ads": "от 24 000 ₽ в месяц за ведение (рекламный бюджет оплачивается отдельно)",
 "seo-geo": "от 40 000 ₽ в месяц",
 "smm-telegram": "от 48 000 ₽ в месяц",
 "web": "от 120 000 ₽ за корпоративный сайт",
 "production": "от 220 000 ₽, срок от 1 месяца",
 "maps": "от 36 000 ₽ в год (годовое размещение карточки в Яндекс Бизнесе или 2ГИС)",
}
for _slug, _s in SERVICES.items():
    if _slug in PRICES:
        _s["faq"] = [(q, a.replace(PRICE_PH, "Ориентир: " + PRICES[_slug] + ".")) for q, a in _s["faq"]]

def service_page(s):
    path = "services/" + s["slug"]
    crumb = [("Главная", "/"), ("Услуги", "/services"), (s["name"], None)]
    parts = [hero(crumb, "Услуга", s["h1"], s["lead"], active="services", ctas=[("pxa-btn", "#pxa-audit", "Обсудить проект"), ("pxa-btn-ghost", "/cases", "Смотреть кейсы")])]
    parts.append(cards("Для кого", s["forwho"], cols=4, sub="Узнайте свою задачу."))
    parts.append(steps("Что входит", s["included"], tint=True))
    r = s["results"]
    if r:
        parts.append(kpi("Результаты", "Цифры из наших кейсов по этой услуге.", r["hero"], [t for t in r["tiles"]], [], "", fn=r.get("fn", False)))
    parts.append(steps("Как работаем", [(t, d, None) for t, d in s["how"]], tint=not r is None and False, cols=2 if len(s["how"]) == 4 else 3))
    fac = "".join(f"<li>{CHECK}<span>{x}</span></li>" for x in s["price_factors"])
    parts.append(f'''<section class="pxa pxa-sec pxa-tint" id="pxa-price"><div class="pxa-wrap"><h2 class="pxa-h2">Стоимость</h2>
<div class="pxa-price"><div class="pxa-panel" style="background:#fff"><h3>Ориентир</h3><p>Мы называем цену после экспресс-аудита и брифа, потому что она зависит от задачи.</p><div class="pxa-big{'' if s['slug'] in PRICES else ' pxa-ph'}">{PRICES.get(s["slug"], PRICE_PH)}</div></div>
<div class="pxa-panel" style="background:#fff"><h3>От чего зависит цена</h3><ul class="pxa-list">{fac}</ul></div></div></div></section>''')
    parts.append(link_cards("Кейсы по услуге", more_for(s["cases"]), tint=False))
    parts.append(faq(s["faq"]))
    parts.append(audit("Обсудить проект", "Расскажите о задаче. Начнём с бесплатного экспресс-аудита: покажем, где теряются заявки, за 3 рабочих дня."))
    rel = "".join(f'<article class="pxa-mc"><small>Смежная услуга</small><h3><a href="/services/{x}">{SERVICES[x]["name"]}</a></h3><p>{SERVICES[x]["short"]}</p><span class="pxa-go" aria-hidden="true">Подробнее →</span></article>' for x in s["related"])
    parts.append(f'<section class="pxa pxa-sec pxa-tint" id="pxa-related"><div class="pxa-wrap"><h2 class="pxa-h2">Смежные услуги</h2><div class="pxa-more-grid pxa-g2">{rel}</div></div></section>')
    parts.append(footer())
    ld = jsonld(breadcrumb_ld([("Главная", "/"), ("Услуги", "/services/"), (s["name"], f"/services/{s['slug']}/")]),
                {"@context": "https://schema.org", "@type": "Service", "name": s["h1"], "serviceType": s["name"], "provider": {"@type": "Organization", "name": "Proxy Agency", "url": SITE + "/"}, "areaServed": "RU", "description": s["desc"]},
                faq_ld(s["faq"]))
    return page(path, s["title"], s["desc"], "site.css", "\n".join(parts), ld)

def hub_page():
    cards_html = "".join(f'<article class="pxa-mc"><small>Услуга</small><h3><a href="/services/{k}">{SERVICES[k]["name"]}</a></h3><p>{SERVICES[k]["result"]}</p><span class="pxa-go" aria-hidden="true">Подробнее →</span></article>' for k in ORDER)
    parts = [hero([("Главная", "/"), ("Услуги", None)], "Услуги", "Услуги digital-агентства Proxy Agency",
                  "Реклама, SEO, карты, соцсети, сайты и продакшн работают как единая система: трафик, сайт, контент и аналитика.", active="services",
                  ctas=[("pxa-btn", "#pxa-audit", "Обсудить проект"), ("pxa-btn-ghost", "/cases", "Смотреть кейсы")])]
    parts.append(f'<section class="pxa pxa-sec" id="pxa-services"><div class="pxa-wrap"><h2 class="pxa-h2">Шесть услуг</h2><div class="pxa-more-grid">{cards_html}</div></div></section>')
    parts.append(steps("Как подобрать услугу", [("Цель", "Что нужно: заявки, бронирования, узнаваемость, выход в новый регион."), ("Бюджет", "Сколько готовы вкладывать в рекламу и продвижение в месяц."), ("Сроки", "К какой дате нужен результат: запуск, сезон, открытие.")], cols=3))
    parts.append(cards("Комплексные решения", [("Ресторан", "Реклама, сайт и аналитика: анонс открытия, акции, онлайн-бронирование. Пример: «Петров-Водкин»."), ("Отель и санаторий", "Сайт, SEO и контекстная реклама со сквозной аналитикой. Пример: «Невский берег»."), ("Бренд и производитель", "SMM, таргет, конкурсы и каналы в Telegram и MAX. Пример: TARGET energy drink.")], cols=3, tint=False, idn="pxa-bundles"))
    parts.append(link_cards("Кейсы по услугам", more_for(["petrov-vodkin", "nevsky-bereg", "target"])))
    parts.append(audit("Обсудить проект", "Расскажите о задаче. Начнём с бесплатного экспресс-аудита: покажем, где теряются заявки, за 3 рабочих дня."))
    parts.append(footer())
    ld = jsonld(breadcrumb_ld([("Главная", "/"), ("Услуги", "/services/")]))
    return page("services", "Услуги digital-агентства в Санкт-Петербурге — Proxy Agency", "Реклама, SEO и GEO, карты и навигаторы, SMM и Telegram, сайты и продакшн от Proxy Agency: услуги, результаты в кейсах, стоимость.", "site.css", "\n".join(parts), ld)
